/**
 * The contract `tooltip.tsx` (native) and `tooltip.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./tooltip` to
 * `tooltip.web.tsx` on web.
 */
import type { ReactNode } from "react";

export type TooltipProviderProps = { children: ReactNode };

export type TooltipProps = { children: ReactNode };

export type TooltipTriggerProps = {
  /** Hand the handlers to the single child rather than wrapping it. */
  asChild?: boolean | undefined;
  children: ReactNode;
};

export type TooltipContentProps = {
  className?: string | undefined;
  children: ReactNode;
};

export const TOOLTIP_CONTENT_CLASS = "overflow-hidden rounded-md border bg-popover px-3 py-1.5";
export const TOOLTIP_TEXT_CLASS = "text-sm text-popover-foreground";

/**
 * The native tooltip: long-press the trigger and the bubble appears above it
 * until the next press or a few seconds pass.
 *
 * Hover does not exist on a touch screen, so radix's trigger has no direct
 * equivalent — but dropping the content entirely would lose the only place
 * some labels are written down. Long-press is the platform's own convention
 * for "tell me more about this control", and it costs no dependency.
 *
 * `Tooltip` wraps its children in a relatively-positioned `View` so the bubble
 * can be absolutely placed against the trigger; on web radix's root is a
 * fragment and the wrapper is not there.
 */

import {
  cloneElement,
  createContext,
  isValidElement,
  type ReactElement,
  useContext,
  useEffect,
  useState,
} from "react";
import { Pressable, Text, View } from "react-native";
import {
  TOOLTIP_CONTENT_CLASS,
  TOOLTIP_TEXT_CLASS,
  type TooltipContentProps,
  type TooltipProps,
  type TooltipProviderProps,
  type TooltipTriggerProps,
} from "@/components/ui/tooltip-base";
import { cn } from "@/lib/utils";

type TooltipState = { open: boolean; setOpen: (open: boolean) => void };

const TooltipContext = createContext<TooltipState>({
  open: false,
  setOpen: () => {},
});

/** Nothing to provide on native; kept so call sites need not branch. */
function TooltipProvider({ children }: TooltipProviderProps) {
  return children;
}

function Tooltip({ children }: TooltipProps) {
  const [open, setOpen] = useState(false);
  return (
    <TooltipContext.Provider value={{ open, setOpen }}>
      <View className="relative">{children}</View>
    </TooltipContext.Provider>
  );
}

function TooltipTrigger({ asChild, children }: TooltipTriggerProps) {
  const { setOpen } = useContext(TooltipContext);
  const show = () => setOpen(true);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onLongPress?: () => void }>, {
      onLongPress: show,
    });
  }
  return <Pressable onLongPress={show}>{children}</Pressable>;
}

/** How long the bubble stays up before dismissing itself. */
const VISIBLE_MS = 2500;

function TooltipContent({ className, children }: TooltipContentProps) {
  const { open, setOpen } = useContext(TooltipContext);

  useEffect(() => {
    if (!open) return;
    const timer = setTimeout(() => setOpen(false), VISIBLE_MS);
    return () => clearTimeout(timer);
  }, [open, setOpen]);

  if (!open) return null;
  return (
    <View
      className={cn("absolute bottom-full z-50 mb-1 self-center", TOOLTIP_CONTENT_CLASS, className)}
      pointerEvents="none"
    >
      <Text className={TOOLTIP_TEXT_CLASS}>{children}</Text>
    </View>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

/**
 * The web tooltip: radix, shown on hover and focus. `tooltip.tsx` is the
 * native counterpart and `tooltip-base.ts` holds the contract they share.
 */

import { Tooltip as TooltipPrimitive } from "radix-ui";
import {
  TOOLTIP_CONTENT_CLASS,
  TOOLTIP_TEXT_CLASS,
  type TooltipContentProps,
  type TooltipProps,
  type TooltipProviderProps,
  type TooltipTriggerProps,
} from "@/components/ui/tooltip-base";
import { cn } from "@/lib/utils";

function TooltipProvider({ children }: TooltipProviderProps) {
  return <TooltipPrimitive.Provider>{children}</TooltipPrimitive.Provider>;
}

function Tooltip({ children }: TooltipProps) {
  return <TooltipPrimitive.Root>{children}</TooltipPrimitive.Root>;
}

function TooltipTrigger({ asChild, children }: TooltipTriggerProps) {
  return <TooltipPrimitive.Trigger asChild={asChild ?? false}>{children}</TooltipPrimitive.Trigger>;
}

function TooltipContent({ className, children }: TooltipContentProps) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        sideOffset={4}
        className={cn(
          "z-50 shadow-md animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
          TOOLTIP_CONTENT_CLASS,
          TOOLTIP_TEXT_CLASS,
          className,
        )}
      >
        {children}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
